/* Synthetic source UI PNG verification and chromakey.
 * No original sprites or copyrighted assets are bundled in this test. */
#include "cnk_source_ui.h"
#include <assert.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>
#include <zlib.h>

/* Original tiny 2x1 RGBA PNG fixture generated by Pillow on 2026-10-11.
 * One exact magenta pixel and one ordinary coloured pixel. */
static const unsigned char png_fixture[]={
 0x89,0x50,0x4e,0x47,0x0d,0x0a,0x1a,0x0a,0x00,0x00,0x00,0x0d,
 0x49,0x48,0x44,0x52,0x00,0x00,0x00,0x02,0x00,0x00,0x00,0x01,
 0x08,0x06,0x00,0x00,0x00,0xf4,0x22,0x7f,0x8a,0x00,0x00,0x00,
 0x11,0x49,0x44,0x41,0x54,0x78,0x9c,0x63,0xf8,0xcf,0xf0,0xff,
 0xbf,0x44,0x83,0xc6,0x09,0x00,0x15,0xee,0x04,0x86,0x8e,0x36,
 0x6c,0x49,0x00,0x00,0x00,0x00,0x49,0x45,0x4e,0x44,0xae,0x42,
 0x60,0x82
};
int main(int argc,char **argv){
 const cnk_source_ui_spec *title=cnk_source_ui_original(CNK_SOURCE_UI_TITLE);
 const cnk_source_ui_spec *wumpa=cnk_source_ui_original(CNK_SOURCE_UI_WUMPA);
 assert(title && title->vfs_index==219 && title->vfs_id==0x89b14497u);
 assert(title->width==326u && title->height==158u);
 assert(wumpa && wumpa->vfs_index==119 && wumpa->vfs_id==0x43bdcefeu);
 assert(!cnk_source_ui_original(CNK_SOURCE_UI_COUNT));
 cnk_source_ui_spec fake={0,0,2,1,0xd570c34cu};
 assert(!cnk_source_ui_verify_png(png_fixture,sizeof(png_fixture),&fake));
 fake.width=3;
 assert(cnk_source_ui_verify_png(png_fixture,sizeof(png_fixture),&fake)<0);
 fake.width=2;fake.raw_png_crc32^=1u;
 assert(cnk_source_ui_verify_png(png_fixture,sizeof(png_fixture),&fake)<0);
 fake.raw_png_crc32^=1u;
 unsigned char damaged[sizeof(png_fixture)];
 memcpy(damaged,png_fixture,sizeof(damaged));damaged[22]^=1u;
 assert(cnk_source_ui_verify_png(damaged,sizeof(damaged),&fake)<0);
 unsigned char rgba[12]={
   255,0,255,255, 24,128,40,200, 255,0,254,127
 };
 size_t removed=999;
 assert(cnk_source_ui_key_magenta(rgba,3,sizeof(rgba)-1,&removed)<0);
 assert(removed==999 && rgba[0]==255);
 assert(!cnk_source_ui_key_magenta(rgba,3,sizeof(rgba),&removed));
 assert(removed==1);
 assert(!rgba[0]&&!rgba[1]&&!rgba[2]&&!rgba[3]);
 assert(rgba[4]==24 && rgba[5]==128 && rgba[6]==40 && rgba[7]==200);
 assert(rgba[8]==255&&rgba[9]==0&&rgba[10]==254&&rgba[11]==127);
 assert(cnk_source_ui_key_magenta(rgba,3,SIZE_MAX,&removed)<0);
 unsigned char *buffer=(unsigned char*)0x1;size_t len=9;
 assert(cnk_source_ui_extract(NULL,CNK_SOURCE_UI_TITLE,&buffer,&len)<0);
 assert(buffer==NULL&&len==0);
 if(argc>1){
  fufs_file original={0};
  assert(!fufs_open(argv[1],&original));
  for(unsigned kind=0;kind<CNK_SOURCE_UI_COUNT;kind++){
   unsigned char *data=NULL;size_t bytes=0;
   assert(!cnk_source_ui_extract(&original,kind,&data,&bytes));
   assert(data && bytes>0);
   free(data);
  }
  fufs_close(&original);
  puts("PASS: both original user-owned Zeebo PNGs match CRC and dimensions");
 }
 puts("PASS: source UI PNG CRC/dimension validation and exact magenta key");
 return 0;
}
